&lt;span id=&#34;cb4-60&#34;&gt;&lt;a href=&#34;#cb4-60&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        &lt;span class=&#34;cf&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(;&lt;/span&gt; l &lt;span class=&#34;op&#34;&gt;&amp;lt;=&lt;/span&gt; r &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; h&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;i&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;=&lt;/span&gt; h&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;r&lt;span class=&#34;op&#34;&gt;]];&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;--&lt;/span&gt;r&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
